<template><div><div class="page-head"><div><h2>系统运行监控</h2><p>最后检测：{{checkedAt||'检测中'}}</p></div><el-button :loading="loading" @click="check">重新检测</el-button></div><el-row :gutter="16"><el-col v-for="s in services" :key="s.name" :span="8"><el-card shadow="hover" class="service"><div><strong>{{s.name}}</strong><small>{{s.desc}}</small></div><el-tag :type="s.ok?'success':'danger'">{{s.ok?'运行正常':'服务异常'}}</el-tag></el-card></el-col></el-row><el-card shadow="never" class="links"><template #header>基础设施入口</template><el-button @click="open('http://localhost:8848/nacos')">Nacos 注册中心</el-button><el-button @click="open('http://localhost:15672')">RabbitMQ</el-button><el-button @click="open('http://localhost:19411')">Zipkin 链路追踪</el-button><el-button @click="open('http://localhost:18080/swagger-ui.html')">API 文档</el-button></el-card></div></template>
<script setup>import{ref}from'vue';import request from '@/utils/request';const loading=ref(false),checkedAt=ref('');const services=ref([{name:'用户服务',desc:'身份认证与账号',path:'/user/profile',auth:true},{name:'课程服务',desc:'课程与内容',path:'/course/category/list'},{name:'订单服务',desc:'交易与支付',path:'/order/admin/stats'},{name:'通知服务',desc:'消息投递',path:'/notify/unread-count'},{name:'推荐服务',desc:'智能推荐策略',path:'/recommendation/admin/config'}]);async function check(){loading.value=true;await Promise.all(services.value.map(async s=>{try{await request.get(s.path);s.ok=true}catch{s.ok=false}}));checkedAt.value=new Date().toLocaleString('zh-CN');loading.value=false}const open=url=>window.open(url,'_blank');check()</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head h2{margin:0}.page-head p,small{color:#909399}.service{margin-bottom:16px}.service :deep(.el-card__body){display:flex;justify-content:space-between;align-items:center}.service small{display:block;margin-top:8px}.links{margin-top:8px}</style>
